// Terminal Compatibility Matrix
// This file is auto-generated by internal/termcompat and documents
// which terminal protocols are supported by common terminal emulators.
//
// Testing methodology: escape sequences verified via TERM env + manual testing.
// Legend: YES = confirmed working, PARTIAL = works but with caveats, NO = not supported

package termcompat

// TerminalSupport documents protocol support across major terminals.
type TerminalSupport struct {
	Name      string
	Term      string // $TERM env value (e.g., "xterm-256color")
	Protocols map[string]Support
}

type Support int

const (
	SupportYes     Support = iota // Fully supported
	SupportPartial                // Works with caveats
	SupportNo                     // Not supported
	SupportUnknown                // Not yet tested
)

