// SupportString returns a human-readable support indicator.
func (s Support) String() string {
	switch s {
	case SupportYes:
		return "YES"
	case SupportPartial:
		return "PARTIAL"
	case SupportNo:
		return "NO"
	default:
		return "UNKNOWN"
	}
}

// CountSupport returns counts of each support level for a given protocol.
func CountSupport(protocol string) (yes, partial, no, unknown int) {
	for _, term := range CompatibilityMatrix {
		switch term.Protocols[protocol] {
		case SupportYes:
			yes++
		case SupportPartial:
			partial++
		case SupportNo:
			no++
		default:
			unknown++
		}
	}
	return
}

// TerminalMatrix is the terminal detection matrix type used by legacy tests.
type TerminalMatrix = TerminalSupport

// AllTerminals returns the compatibility matrix entries.
func AllTerminals() []TerminalMatrix {
	return CompatibilityMatrix
}

// DetectForMatrix returns capabilities for a terminal matrix entry.
func DetectForMatrix(tm TerminalMatrix) TerminalCapabilities {
	return TerminalCapabilities{Name: tm.Name, Term: tm.Term, Protocols: tm.Protocols}
}

// TerminalCapabilities wraps terminal detection results for legacy tests.
type TerminalCapabilities struct {
	Name      string
	Term      string
	Protocols map[string]Support
}

// Has returns true if the protocol is supported (YES or PARTIAL).
func (c TerminalCapabilities) Has(protocol string) bool {
	s, ok := c.Protocols[protocol]
	return ok && s != SupportNo
}

// SSHTerminalMatrix returns a default terminal matrix for SSH sessions.
func SSHTerminalMatrix() TerminalMatrix {
	return TerminalMatrix{
		Name:      "SSH (generic)",
		Protocols: map[string]Support{},
	}
}
